  "＋ Add my own question": { es: "＋ Añadir mi propia pregunta", ar: "＋ أضف سؤالي الخاص", zh: "＋ 添加我自己的题目", sw: "＋ Ongeza swali langu", sv: "＋ Lägg till egen fråga", de: "＋ Eigene Frage hinzufügen", pt: "＋ Adicionar minha própria pergunta", fr: "＋ Ajouter ma propre question" },
  "Delete saved quiz": { es: "Borrar cuestionario guardado", ar: "احذف الاختبار المحفوظ", zh: "删除已保存的测验", sw: "Futa jaribio lililohifadhiwa", sv: "Radera sparat quiz", de: "Gespeichertes Quiz löschen", pt: "Excluir quiz salvo", fr: "Supprimer le quiz enregistré" },
  "No questions yet — add suggested ones or write your own.": { es: "Aún no hay preguntas: añade sugeridas o escribe las tuyas.", ar: "لا أسئلة بعد — أضف أسئلة مقترحة أو اكتب أسئلتك.", zh: "还没有题目——添加推荐题或自己写。", sw: "Bado hakuna maswali — ongeza yaliyopendekezwa au andika yako.", sv: "Inga frågor än — lägg till föreslagna eller skriv egna.", de: "Noch keine Fragen — füge vorgeschlagene hinzu oder schreib eigene.", pt: "Ainda sem perguntas — adicione sugeridas ou escreva as suas.", fr: "Pas encore de questions — ajoutez-en des suggérées ou écrivez les vôtres." },
  "▶ Play my quiz": { es: "▶ Jugar mi cuestionario", ar: "▶ العب اختباري", zh: "▶ 玩我的测验", sw: "▶ Cheza jaribio langu", sv: "▶ Spela mitt quiz", de: "▶ Mein Quiz spielen", pt: "▶ Jogar meu quiz", fr: "▶ Jouer à mon quiz" },
