  "Clear this quiz?": { es: "¿Borrar este cuestionario?", ar: "هل تريد مسح هذا الاختبار؟", zh: "清空这份测验？", sw: "Futa jaribio hili?", sv: "Rensa det här quizet?", de: "Dieses Quiz leeren?", pt: "Limpar este quiz?", fr: "Vider ce quiz ?" },
